/// `text` with each pair of [`COMPOSITIONS`] as its single letter; the letter made can compose
/// again with the next one.
pub(super) fn indic_normal(text: &str) -> String {
    let mut s: Vec<char> = text.chars().collect();
    let mut i = 0;
    while i + 1 < s.len() {
        match COMPOSITIONS.iter().find(|&&(a, b, _)| a == s[i] && b == s[i + 1]) {
            Some(&(_, _, to)) => {
                s[i] = to;
                s.remove(i + 1);
            }
            None => i += 1,
        }
    }
    s.into_iter().collect()
}

/// `text` with the Hindi spelling variants folded (L. Larkey, "Hindi CLIR in thirty days"): a
/// dead `न` as anusvara, chandrabindu as anusvara, nukta forms as their plain letters, long
/// vowels as short ones, and without nukta, virama and zero-width joiners.
pub(super) fn hindi_normal(text: &str) -> String {
    let c: Vec<char> = text.chars().collect();
    let mut out = String::with_capacity(text.len());
    let mut i = 0;
    while i < c.len() {
        let ch = c[i];
        i += 1;
        if ch == '\u{928}' && c.get(i) == Some(&'\u{94D}') {
            out.push('\u{902}');
            i += 1;
            continue;
        }
        let folded = match ch {
            '\u{93C}' | '\u{200D}' | '\u{200C}' | '\u{94D}' => continue,
            '\u{901}' => '\u{902}',
            '\u{929}' => '\u{928}',
            '\u{931}' => '\u{930}',
            '\u{934}' => '\u{933}',
            '\u{958}' => '\u{915}',
            '\u{959}' => '\u{916}',
            '\u{95A}' => '\u{917}',
            '\u{95B}' => '\u{91C}',
            '\u{95C}' => '\u{921}',
            '\u{95D}' => '\u{922}',
            '\u{95E}' => '\u{92B}',
            '\u{95F}' => '\u{92F}',
            '\u{945}' | '\u{946}' | '\u{948}' => '\u{947}',
            '\u{949}' | '\u{94A}' | '\u{94C}' => '\u{94B}',
            '\u{90D}' | '\u{90E}' | '\u{910}' => '\u{90F}',
            '\u{911}' | '\u{912}' | '\u{914}' => '\u{913}',
            '\u{972}' | '\u{906}' => '\u{905}',
            '\u{908}' => '\u{907}',
            '\u{90A}' => '\u{909}',
            '\u{960}' => '\u{90B}',
            '\u{961}' => '\u{90C}',
            '\u{940}' => '\u{93F}',
            '\u{942}' => '\u{941}',
            '\u{944}' => '\u{943}',
            '\u{963}' => '\u{962}',
            ch => ch,
        };
        out.push(folded);
    }
    out
}

