/// The Hindi stem of a normalized word.
pub(super) fn hindi_stem(text: &str) -> String {
    let w: Vec<char> = text.chars().collect();
    for &(more_than, list) in HINDI_ENDINGS {
        if let Some(e) = list.iter().find(|e| w.len() > more_than && ends(&w, e)) {
            return w[..w.len() - e.chars().count()].iter().collect();
        }
    }
    text.to_string()
}

/// The Bengali virama (hasanta).
const HASANTA: char = '\u{9CD}';

/// `text` in one Bengali spelling: long vowel signs as short ones, `শ` and `ষ` as `স`, `ণ` as
/// `ন`, `ঙ` as anusvara, `ড়` and `ঢ়` as `র`, khanda ta as `ত`, without chandrabindu, with the
/// ya-phala and ba-phala conjuncts reduced and the visarga doubled into the next letter or
/// dropped at the end.
pub(super) fn bengali_normal(text: &str) -> String {
    let mut s: Vec<char> = text.chars().collect();
    let mut i: isize = 0;
    while (i as usize) < s.len() {
        let at = i as usize;
        match s[at] {
            '\u{981}' => {
                s.remove(at);
                continue;
            }
            '\u{9C0}' => s[at] = '\u{9BF}',
            '\u{9C2}' => s[at] = '\u{9C1}',
            '\u{999}' => s[at] = '\u{982}',
            '\u{9AF}' => i = bengali_ya_phala(&mut s, at),
            '\u{9AC}' => i = bengali_ba_phala(&mut s, at),
            '\u{983}' if at + 1 == s.len() => {
                if s.len() <= 3 {
                    s[at] = '\u{9B9}';
                } else {
                    s.remove(at);
                    continue;
                }
            }
            '\u{983}' => s[at] = s[at + 1],
            '\u{9B6}' | '\u{9B7}' => s[at] = '\u{9B8}',
            '\u{9A3}' => s[at] = '\u{9A8}',
            '\u{9DC}' | '\u{9DD}' => s[at] = '\u{9B0}',
            '\u{9CE}' => s[at] = '\u{9A4}',
            _ => {}
        }
        i += 1;
    }
    s.into_iter().collect()
}

/// A `য` at `at` after a hasanta: right after the first letter it becomes the vowel sign `ে`
/// (with a following `া` dropped), elsewhere the conjunct goes. Returns where to go on from, less
/// one.
fn bengali_ya_phala(s: &mut Vec<char>, at: usize) -> isize {
    if at == 2 && s[1] == HASANTA {
        s[1] = '\u{9C7}';
        if s.get(at + 1) == Some(&'\u{9BE}') {
            s.remove(at + 1);
        }
        s.remove(at);
        return at as isize - 1;
    }
    if at >= 1 && s[at - 1] == HASANTA {
        s.drain(at - 1..=at);
        return at as isize - 2;
    }
    at as isize
}

/// A `ব` at `at` after a hasanta: after the first letter or after another conjunct the pair
/// goes, otherwise the letter before the hasanta is doubled in its place. Returns where to go on
/// from, less one.
fn bengali_ba_phala(s: &mut Vec<char>, at: usize) -> isize {
    if at == 0 || s[at - 1] != HASANTA {
        return at as isize;
    }
    if at == 2 || (at >= 5 && s[at - 3] == HASANTA) {
        s.drain(at - 1..=at);
        return at as isize - 2;
    }
    if at >= 2 {
        s[at - 1] = s[at - 2];
        s.remove(at);
        return at as isize - 1;
    }
    at as isize
}

